package com.chubb.apac.claims.modulith.config.service;
import com.chubb.apac.claims.modulith.common.enums.*;import com.chubb.apac.claims.modulith.common.exception.ResourceNotFoundException;import com.chubb.apac.claims.modulith.config.mapper.ConfigurationMapper;import com.chubb.apac.claims.modulith.config.model.*;import com.chubb.apac.claims.modulith.config.repository.*;import com.chubb.apac.claims.modulith.config.service.impl.ConfigurationQueryServiceImpl;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class ConfigurationQueryServiceImplTest {
 MarketConfigurationRepository markets=mock(MarketConfigurationRepository.class);ProductConfigurationRepository products=mock(ProductConfigurationRepository.class);BusinessRuleRepository rules=mock(BusinessRuleRepository.class);SlaConfigurationRepository slas=mock(SlaConfigurationRepository.class);ConfigurationQueryServiceImpl service=new ConfigurationQueryServiceImpl(markets,products,rules,slas,new ConfigurationMapper());
 @Test void listsActiveProducts(){MarketConfiguration m=new MarketConfiguration();m.setMarket(Market.SG);ProductConfiguration p=new ProductConfiguration();p.setMarket(Market.SG);p.setProductType(ProductType.MOTOR);p.setClaimLimitMin(BigDecimal.ZERO);p.setClaimLimitMax(BigDecimal.TEN);when(markets.findByMarketAndActiveTrue(Market.SG)).thenReturn(Optional.of(m));when(products.findByMarketAndActiveTrueOrderByProductTypeAsc(Market.SG)).thenReturn(List.of(p));assertThat(service.products(Market.SG)).extracting(x->x.type()).containsExactly(ProductType.MOTOR);}
 @Test void rejectsUnsupportedMarket(){when(markets.findByMarketAndActiveTrue(Market.SG)).thenReturn(Optional.empty());assertThatThrownBy(()->service.products(Market.SG)).isInstanceOf(ResourceNotFoundException.class);}
}
